        assert_eq!(value["exit_code"], json!(0));
        assert_eq!(value["success"], json!(true));
        assert_eq!(value["timed_out"], json!(false));
        assert!(
            value["stdout"]
                .as_str()
                .unwrap_or("")
                .contains("hello-process"),
            "stdout should capture argv output, got {}",
            value["stdout"]
        );
        let _ = fs::remove_dir_all(data_dir);
